  1687  /*  For SHT_GROUP sections. */
  1688  static int
  1689  read_gs_section_group(
  1690      dwarf_elf_object_access_internals_t *ep,
  1691      struct generic_shdr* psh,
  1692      int *errcode)
  1693  {
  1694      Dwarf_Unsigned i = 0;
  1695      int res = 0;
  1696
  1697      if (!psh->gh_sht_group_array) {
  1698          Dwarf_Unsigned seclen = psh->gh_size;
  1699          char *data = 0;
  1700          char *dp = 0;
  1701          Dwarf_Unsigned* grouparray = 0;
  1702          char dblock[4];
  1703          Dwarf_Unsigned va = 0;
  1704          Dwarf_Unsigned count = 0;
  1705          int foundone = 0;
  1706
  1707          if (seclen < DWARF_32BIT_SIZE) {
  1708              *errcode = DW_DLE_ELF_SECTION_GROUP_ERROR;
  1709              return DW_DLV_ERROR;
  1710          }
  1711          data = malloc(seclen);
  1712          if (!data) {
  1713              *errcode = DW_DLE_ALLOC_FAIL;
  1714              return DW_DLV_ERROR;
  1715          }
  1716          dp = data;
  1717          if (psh->gh_entsize != DWARF_32BIT_SIZE) {
  1718              *errcode = DW_DLE_ELF_SECTION_GROUP_ERROR;
  1719              free(data);
  1720              return DW_DLV_ERROR;
  1721          }
  1722          if (!psh->gh_entsize) {
  1723              free(data);
  1724              *errcode = DW_DLE_ELF_SECTION_GROUP_ERROR;
  1725              return DW_DLV_ERROR;
  1726          }
  1727          count = seclen/psh->gh_entsize;
  1728          if (count > ep->f_loc_shdr.g_count) {
  1729              /* Impossible */
  1730              free(data);
  1731              *errcode = DW_DLE_ELF_SECTION_GROUP_ERROR;
  1732              return DW_DLV_ERROR;
  1733          }
  1734          res = RRMOA(ep->f_fd,data,psh->gh_offset,seclen,
  1735              ep->f_filesize,errcode);
  1736          if (res != DW_DLV_OK) {
  1737              free(data);
  1738              return res;
  1739          }
  1740          grouparray = malloc(count * sizeof(Dwarf_Unsigned));
  1741          if (!grouparray) {
  1742              free(data);
  1743              *errcode = DW_DLE_ALLOC_FAIL;
  1744              return DW_DLV_ERROR;
  1745          }
  1746
  1747          memcpy(dblock,dp,DWARF_32BIT_SIZE);
  1748          ASNAR(memcpy,va,dblock);
  1749          /* There is ambiguity on the endianness of this stuff. */
  1750          if (va != 1 && va != 0x1000000) {
  1751              /*  Could be corrupted elf object. */
  1752              *errcode = DW_DLE_ELF_SECTION_GROUP_ERROR;
  1753              free(data);
  1754              free(grouparray);
  1755              return DW_DLV_ERROR;
  1756          }
  1757          grouparray[0] = 1;
  1758          dp = dp + DWARF_32BIT_SIZE;
  1759          for ( i = 1; i < count; ++i,dp += DWARF_32BIT_SIZE) {
  1760              Dwarf_Unsigned gseca = 0;
  1761              Dwarf_Unsigned gsecb = 0;
  1762              struct generic_shdr* targpsh = 0;
  1763
  1764              memcpy(dblock,dp,DWARF_32BIT_SIZE);
  1765              ASNAR(memcpy,gseca,dblock);
  1766              ASNAR(_dwarf_memcpy_swap_bytes,gsecb,dblock);
  1767              if (!gseca) {
  1768                  free(data);
  1769                  free(grouparray);
  1770                  *errcode = DW_DLE_ELF_SECTION_GROUP_ERROR;
  1771                  return DW_DLV_ERROR;
  1772              }
  1773              grouparray[i] = gseca;
  1774              if (gseca > ep->f_loc_shdr.g_count) {
  1775                  /*  Might be confused endianness by
  1776                      the compiler generating the SHT_GROUP.
  1777                      This is pretty horrible. */
  1778
  1779                  if (gsecb > ep->f_loc_shdr.g_count) {
  1780                      *errcode = DW_DLE_ELF_SECTION_GROUP_ERROR;
  1781                      free(data);
  1782                      free(grouparray);
  1783                      return DW_DLV_ERROR;
  1784                  }
  1785                  /* Ok. Yes, ugly. */
  1786                  gseca = gsecb;
  1787                  grouparray[i] = gseca;
  1788              }
  1789              targpsh = ep->f_shdr + gseca;
  1790              if (targpsh->gh_section_group_number) {
  1791                  /* multi-assignment to groups. Oops. */
  1792                  free(data);
  1793                  free(grouparray);
  1794                  *errcode = DW_DLE_ELF_SECTION_GROUP_ERROR;
  1795                  return DW_DLV_ERROR;
  1796              }
  1797              targpsh->gh_section_group_number =
  1798                  ep->f_sg_next_group_number;
  1799              foundone = 1;
  1800          }
  1801          if (foundone) {
  1802              ++ep->f_sg_next_group_number;
  1803              ++ep->f_sht_group_type_section_count;
  1804          }
  1805          free(data);
  1806          psh->gh_sht_group_array = grouparray;
  1807          psh->gh_sht_group_array_count = count;
  1808      }
  1809      return DW_DLV_OK;
  1810  }
  1811  /*  Does related things.
  1812      A)  Counts the number of SHT_GROUP
  1813          and for each builds an array of the sections in the group
  1814          (which we expect are all DWARF-related)
  1815          and sets the group number in each mentioned section.
  1816      B)  Counts the number of SHF_GROUP flags.
  1817      C)  If gnu groups:
  1818          ensure all the DWARF sections marked with right group
  1819          based on A(we will mark unmarked as group 1,
  1820          DW_GROUPNUMBER_BASE).
  1821      D)  If arm groups (SHT_GROUP zero, SHF_GROUP non-zero):
  1822          Check the relocations of all SHF_GROUP section
  1823          FIXME: algorithm needed.
  1824
  1825      If SHT_GROUP and SHF_GROUP this is GNU groups.
  1826      If no SHT_GROUP and have SHF_GROUP this is
  1827      arm cc groups and we must use relocation information
  1828      to identify the group members.
  1829
  1830      It seems(?) impossible for an object to have both
  1831      dwo sections and (SHF_GROUP or SHT_GROUP), but
  1832      we do not rule that out here.  */
  1833  static int
  1834  _dwarf_elf_setup_all_section_groups(
  1835      dwarf_elf_object_access_internals_t *ep,
  1836      int *errcode)
  1837  {
  1838      struct generic_shdr* psh = 0;
  1839      Dwarf_Unsigned i = 0;
  1840      Dwarf_Unsigned count = 0;
  1841      int res = 0;
  1842
  1843      count = ep->f_loc_shdr.g_count;
  1844      psh = ep->f_shdr;
  1845
  1846      /* Does step A and step B */
  1847      for (i = 0; i < count; ++psh,++i) {
  1848          const char *name = psh->gh_namestring;
  1849          if (is_empty_section(psh->gh_type)) {
  1850              /*  No data here. */
  1851              continue;
  1852          }
  1853          if (!elf_sht_groupsec(psh->gh_type,name)) {
  1854              /* Step B */
  1855              if (elf_flagmatches(psh->gh_flags,SHF_GROUP)) {
  1856                  ep->f_shf_group_flag_section_count++;
  1857              }
  1858              continue;
  1859          }
  1860          /* Looks like a section group. Do Step A. */
  1861          res  =read_gs_section_group(ep,psh,errcode);
  1862          if (res != DW_DLV_OK) {
  1863              return res;
  1864          }
  1865      }
  1866      /*  Any sections not marked above or here are in
  1867          grep DW_GROUPNUMBER_BASE (1).
  1868          Section C. */
  1869      psh = ep->f_shdr;
  1870      for (i = 0; i < count; ++psh,++i) {
  1871          const char *name = psh->gh_namestring;
  1872          int is_rel = FALSE;
  1873          int is_rela = FALSE;
  1874
  1875          if (is_empty_section(psh->gh_type)) {
  1876              /*  No data here. */
  1877              continue;
  1878          }
  1879          if (elf_sht_groupsec(psh->gh_type,name)) {
  1880              continue;
  1881          }
  1882          /* Not a section group */
  1883          if (string_endswith(name,".dwo")) {
  1884              if (psh->gh_section_group_number) {
  1885                  /* multi-assignment to groups. Oops. */
  1886                  *errcode = DW_DLE_ELF_SECTION_GROUP_ERROR;
  1887                  return DW_DLV_ERROR;
  1888              }
  1889              psh->gh_is_dwarf = TRUE;
  1890              psh->gh_section_group_number = DW_GROUPNUMBER_DWO;
  1891              ep->f_dwo_group_section_count++;
  1892          } else if (_dwarf_load_elf_section_is_dwarf(name,
  1893              &is_rela,&is_rel)) {
  1894              if (!psh->gh_section_group_number) {
  1895                  psh->gh_section_group_number = DW_GROUPNUMBER_BASE;
  1896              }
  1897              psh->gh_is_dwarf = TRUE;
  1898          } else {
  1899              /* Do nothing. */
  1900          }
  1901      }
  1902      if (ep->f_sht_group_type_section_count) {
  1903          /*  Not ARM. Done. */
  1904      }
  1905      if (!ep->f_shf_group_flag_section_count) {
  1906          /*  Nothing more to do. */
  1907          return DW_DLV_OK;
  1908      }
  1909      return DW_DLV_OK;
  1910  }
